class Solution:
    def makeStringSorted(self, s: str) -> int:
        MOD = 10 ** 9 + 7
        t = list(s)
        ops = 0
        while True:
            n = len(t)
            i = -1
            for k in range(n - 1, 0, -1):
                if t[k] < t[k - 1]:
                    i = k
                    break
            if i == -1:
                break
            j = i
            while j + 1 < n and t[j + 1] < t[i - 1]:
                j += 1
            t[i - 1], t[j] = t[j], t[i - 1]
            t[i:] = reversed(t[i:])
            ops += 1
        return ops % MOD

