class Solution {
public:
    int makeStringSorted(string s) {
        const long long MOD = 1e9 + 7;
        string t = s;
        long long ops = 0;
        while (true) {
            int n = t.size(), i = -1;
            for (int k = n - 1; k >= 1; k--)
                if (t[k] < t[k - 1]) { i = k; break; }
            if (i == -1) break;
            int j = i;
            while (j + 1 < n && t[j + 1] < t[i - 1]) j++;
            swap(t[i - 1], t[j]);
            reverse(t.begin() + i, t.end());
            ops++;
        }
        return (int)(ops % MOD);
    }
};

