import java.util.*;

class Solution {
    public int makeStringSorted(String s) {
        final long MOD = 1_000_000_007L;
        char[] t = s.toCharArray();
        long ops = 0;
        while (true) {
            int n = t.length, i = -1;
            for (int k = n - 1; k >= 1; k--) {
                if (t[k] < t[k - 1]) { i = k; break; }
            }
            if (i == -1) break;
            int j = i;
            while (j + 1 < n && t[j + 1] < t[i - 1]) j++;
            char tmp = t[i - 1];
            t[i - 1] = t[j];
            t[j] = tmp;
            for (int l = i, r = n - 1; l < r; l++, r--) {
                char c = t[l];
                t[l] = t[r];
                t[r] = c;
            }
            ops++;
        }
        return (int) (ops % MOD);
    }
}

