var makeStringSorted = function(s) {
    const MOD = 1e9 + 7;
    const t = s.split('');
    let ops = 0;
    while (true) {
        const n = t.length;
        let i = -1;
        for (let k = n - 1; k >= 1; k--) {
            if (t[k] < t[k - 1]) { i = k; break; }
        }
        if (i === -1) break;
        let j = i;
        while (j + 1 < n && t[j + 1] < t[i - 1]) j++;
        [t[i - 1], t[j]] = [t[j], t[i - 1]];
        const suffix = t.slice(i).reverse();
        t.length = i;
        t.push(...suffix);
        ops++;
    }
    return ops % MOD;
};

