class Solution {
public:
    int makeStringSorted(string s) {
        const long long MOD = 1e9 + 7;
        auto power = [&](long long b, long long e) {
            long long r = 1;
            while (e > 0) {
                if (e & 1) r = r * b % MOD;
                b = b * b % MOD;
                e >>= 1;
            }
            return r;
        };
        int n = s.size();
        vector<long long> fact(n + 1, 1), invFact(n + 1, 1);
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = power(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;
        int cnt[26] = {0};
        for (char c : s) cnt[c - 'a']++;
        long long denomInv = 1;
        for (int c : cnt) denomInv = denomInv * invFact[c] % MOD;
        long long ans = 0;
        int rem = n;
        for (char ch : s) {
            int x = ch - 'a';
            rem--;
            long long smaller = 0;
            for (int c = 0; c < x; c++) smaller += cnt[c];
            ans = (ans + smaller * fact[rem] % MOD * denomInv) % MOD;
            denomInv = denomInv * cnt[x] % MOD;
            cnt[x]--;
        }
        return (int)ans;
    }
};

