import java.util.*;

class Solution {
    public int makeStringSorted(String s) {
        final long MOD = 1_000_000_007L;
        int n = s.length();
        long[] fact = new long[n + 1];
        Arrays.fill(fact, 1);
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        long[] invFact = new long[n + 1];
        Arrays.fill(invFact, 1);
        invFact[n] = power(fact[n], MOD);
        for (int i = n; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        long denomInv = 1;
        for (int c : cnt) denomInv = denomInv * invFact[c] % MOD;
        long ans = 0;
        int rem = n;
        for (char ch : s.toCharArray()) {
            int x = ch - 'a';
            rem--;
            long smaller = 0;
            for (int c = 0; c < x; c++) smaller += cnt[c];
            ans = (ans + smaller * fact[rem] % MOD * denomInv) % MOD;
            denomInv = denomInv * cnt[x] % MOD;
            cnt[x]--;
        }
        return (int) ans;
    }

    private long power(long b, long mod) {
        long e = mod - 2, r = 1;
        b %= mod;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % mod;
            b = b * b % mod;
            e >>= 1;
        }
        return r;
    }
}

