/**
 * @param {string} s
 * @return {number}
 */
var makeStringSorted = function(s) {
    const MOD = 1e9 + 7;
    const mulMod = (a, b) => {
        const hi = Math.floor(b / 32768), lo = b % 32768;
        return ((hi * a % MOD) * 32768 % MOD + lo * a % MOD) % MOD;
    };
    const powMod = (b, e) => {
        let r = 1;
        b %= MOD;
        while (e > 0) {
            if (e & 1) r = mulMod(r, b);
            b = mulMod(b, b);
            e >>= 1;
        }
        return r;
    };
    const n = s.length;
    const fact = new Array(n + 1).fill(1);
    const invFact = new Array(n + 1).fill(1);
    for (let i = 1; i <= n; i++) fact[i] = mulMod(fact[i - 1], i);
    invFact[n] = powMod(fact[n], MOD - 2);
    for (let i = n; i >= 1; i--) invFact[i - 1] = mulMod(invFact[i], i);
    const cnt = new Array(26).fill(0);
    for (const ch of s) cnt[ch.charCodeAt(0) - 97]++;
    let denomInv = 1;
    for (const c of cnt) denomInv = mulMod(denomInv, powMod(fact[c], MOD - 2));
    let ans = 0;
    let rem = n;
    for (const ch of s) {
        const x = ch.charCodeAt(0) - 97;
        rem--;
        let smaller = 0;
        for (let c = 0; c < x; c++) smaller += cnt[c];
        ans = (ans + mulMod(mulMod(smaller, fact[rem]), denomInv)) % MOD;
        denomInv = mulMod(denomInv, cnt[x]);
        cnt[x]--;
    }
    return ans;
};
